/**
 * Objek runtime model yang dibagikan ke EditorEngine untuk apply_ai.
 */
open class ModelRuntime: Disposable, AutoCloseable, ModelRuntimeInterface
{

    constructor(pointer: Pointer) {
        this.pointer = pointer
        this.cleanable = UniffiLib.CLEANER.register(this, UniffiCleanAction(pointer))
    }

    /**
     * This constructor can be used to instantiate a fake object. Only used for tests. Any
     * attempt to actually use an object constructed this way will fail as there is no
     * connected Rust object.
     */
    @Suppress("UNUSED_PARAMETER")
    constructor(noPointer: NoPointer) {
        this.pointer = null
        this.cleanable = UniffiLib.CLEANER.register(this, UniffiCleanAction(pointer))
    }
    /**
     * Buat runtime. `dylib_path` boleh kosong bila ORT_DYLIB_PATH terpasang
     * atau library ditemukan lewat jalur pemuat sistem.
     */
    constructor(`dylibPath`: kotlin.String) :
        this(
    uniffiRustCallWithError(EngineException) { _status ->
    UniffiLib.INSTANCE.uniffi_eraser_core_fn_constructor_modelruntime_new(
        FfiConverterString.lower(`dylibPath`),_status)
}
    )

    protected val pointer: Pointer?
    protected val cleanable: UniffiCleaner.Cleanable

    private val wasDestroyed = AtomicBoolean(false)
    private val callCounter = AtomicLong(1)

    override fun destroy() {
        // Only allow a single call to this method.
        // TODO: maybe we should log a warning if called more than once?
        if (this.wasDestroyed.compareAndSet(false, true)) {
            // This decrement always matches the initial count of 1 given at creation time.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable.clean()
            }
        }
    }

    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithPointer(block: (ptr: Pointer) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the pointer being freed concurrently.
        try {
            return block(this.uniffiClonePointer())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val pointer: Pointer?) : Runnable {
        override fun run() {
            pointer?.let { ptr ->
                uniffiRustCall { status ->
                    UniffiLib.INSTANCE.uniffi_eraser_core_fn_free_modelruntime(ptr, status)
                }
            }
        }
    }

    fun uniffiClonePointer(): Pointer {
        return uniffiRustCall() { status ->
            UniffiLib.INSTANCE.uniffi_eraser_core_fn_clone_modelruntime(pointer!!, status)
        }
    }

    override fun `isRegistered`(`id`: kotlin.String): kotlin.Boolean {
            return FfiConverterBoolean.lift(
    callWithPointer {
    uniffiRustCall() { _status ->
    UniffiLib.INSTANCE.uniffi_eraser_core_fn_method_modelruntime_is_registered(
        it, FfiConverterString.lower(`id`),_status)
}
    }
    )
    }
    

    
    /**
     * Daftarkan model dari file ONNX di disk. File harus ada; sesi belum
     * dibuat di sini (dibuat saat inference pertama agar registrasi murah).
     */
    @Throws(EngineException::class)override fun `registerModel`(`id`: kotlin.String, `path`: kotlin.String, `kind`: ModelKind, `inputWidth`: kotlin.UInt, `inputHeight`: kotlin.UInt)
        = 
    callWithPointer {
    uniffiRustCallWithError(EngineException) { _status ->
    UniffiLib.INSTANCE.uniffi_eraser_core_fn_method_modelruntime_register_model(
        it, FfiConverterString.lower(`id`),FfiConverterString.lower(`path`),FfiConverterTypeModelKind.lower(`kind`),FfiConverterUInt.lower(`inputWidth`),FfiConverterUInt.lower(`inputHeight`),_status)
}
    }
    
    

    override fun `registeredIds`(): List<kotlin.String> {
            return FfiConverterSequenceString.lift(
    callWithPointer {
    uniffiRustCall() { _status ->
    UniffiLib.INSTANCE.uniffi_eraser_core_fn_method_modelruntime_registered_ids(
        it, _status)
}
    }
    )
    }
    

    
    /**
     * Aktif/nonaktifkan NNAPI (eksperimental) untuk sesi yang dibuat
     * setelah panggilan ini. Sesi yang sudah berjalan tidak berubah.
     */
    @Throws(EngineException::class)override fun `setUseNnapi`(`enabled`: kotlin.Boolean)
        = 
    callWithPointer {
    uniffiRustCallWithError(EngineException) { _status ->
    UniffiLib.INSTANCE.uniffi_eraser_core_fn_method_modelruntime_set_use_nnapi(
        it, FfiConverterBoolean.lower(`enabled`),_status)
}
    }
    
    

    
    /**
     * Lepas model dan sesinya dari runtime. True bila model ada.
     */override fun `unloadModel`(`id`: kotlin.String): kotlin.Boolean {
            return FfiConverterBoolean.lift(
    callWithPointer {
    uniffiRustCall() { _status ->
    UniffiLib.INSTANCE.uniffi_eraser_core_fn_method_modelruntime_unload_model(
        it, FfiConverterString.lower(`id`),_status)
}
    }
    )
    }
    

    override fun `useNnapi`(): kotlin.Boolean {
            return FfiConverterBoolean.lift(
    callWithPointer {
