/**
 * @suppress
 */
public object FfiConverterTypeModelRuntime: FfiConverter<ModelRuntime, Pointer> {

    override fun lower(value: ModelRuntime): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): ModelRuntime {
        return ModelRuntime(value)
    }

    override fun read(buf: ByteBuffer): ModelRuntime {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: ModelRuntime) = 8UL

    override fun write(value: ModelRuntime, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



